<details>
<summary>Reproduction driver and captured native CLI output</summary>

Only temporary fixture roots are replaced with `<fixture>`. The JSON retains recorded child stdout/stderr, exit status, timings, transport observations and actual disk readback; these are captured results, not expected output. Run this driver against separately built base/head checkouts with `node driver.mjs CHECKOUT red|green RECEIPT.json`. The driver's build-head assertion must pass.

```js
import assert from 'node:assert/strict';
import { execFileSync, spawn } from 'node:child_process';
import { createHash } from 'node:crypto';
import fs from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';

const [checkout, expectation, output] = process.argv.slice(2);
assert(checkout && output && ['red', 'green'].includes(expectation));
const sha256 = data => createHash('sha256').update(data).digest('hex');
const head = execFileSync('/usr/bin/git', ['rev-parse', 'HEAD'], { cwd: checkout, encoding: 'utf8' }).trim();
const build = JSON.parse(await fs.readFile(path.join(checkout, 'dist/build-info.json'), 'utf8'));
assert.equal(build.commit, head);
const root = await fs.mkdtemp(path.join(os.tmpdir(), 'leon-openshell-file-proof-'));
const home = path.join(root, 'home'), state = path.join(root, 'state'), workspace = path.join(root, 'workspace');
await Promise.all([home, state, workspace].map(dir => fs.mkdir(dir, { recursive: true })));
const remoteLog = path.join(root, 'transport-fixture.jsonl');
const command = path.join(root, 'openshell-fixture');
await fs.writeFile(command, '#!/usr/bin/env node\n' +
  'const fs=require("node:fs"); fs.appendFileSync(' + JSON.stringify(remoteLog) +
  ',JSON.stringify({argv:process.argv.slice(2)})+"\\n"); process.exitCode=23;\n', { mode: 0o700 });
const configPath = path.join(root, 'openclaw.json');
const config = JSON.stringify({
  gateway: { mode: 'local' },
  agents: { ownership: 'explicit', entries: { main: { workspace } }, defaults: { systemAgent: { agentId: 'main' } } },
  plugins: { allow: ['openshell'], slots: { memory: 'none' }, entries: {
    openshell: { enabled: true, config: { command, gateway: 'fixture', workspace: 'workers', providers: ['synthetic-broker'], worker: { model: {
      provider: 'openai', id: 'worker-model', api: 'openai-responses', baseUrl: 'https://api.openai.com/v1',
      credentialEnv: 'SYNTHETIC_WORKER_KEY', contextWindow: 8192, maxTokens: 1024,
    } } } },
  } },
  logging: { file: path.join(root, 'runtime.log'), consoleLevel: 'error' },
});
await fs.writeFile(configPath, config);
const env = {
  PATH: process.env.PATH, LANG: 'C.UTF-8', NO_COLOR: '1', HOME: home, OPENCLAW_HOME: home,
  OPENCLAW_STATE_DIR: state, OPENCLAW_CONFIG_PATH: configPath, OPENCLAW_NO_RESPAWN: '1',
  OPENCLAW_SKIP_CHANNELS: '1', OPENCLAW_HIDE_BANNER: '1', OPENCLAW_SKIP_STARTUP_MODEL_PREWARM: '1',
  XDG_DATA_HOME: path.join(home, '.local/share'), XDG_CONFIG_HOME: path.join(home, '.config'),
  XDG_CACHE_HOME: path.join(home, '.cache'),
};
const receipt = { head, build, expectation, root, node: process.version, at: new Date().toISOString(),
  driverSha256: sha256(await fs.readFile(new URL(import.meta.url))), calls: [],
  transport: 'Local executable fixture that refuses provider attachment; no OpenShell daemon, sandbox, node or model request is used.' };
async function readTransport() {
  try { return (await fs.readFile(remoteLog, 'utf8')).trim().split('\n').filter(Boolean).map(JSON.parse); }
  catch (error) { if (error.code === 'ENOENT') return []; throw error; }
}
async function run(label, input, deadlineMs = 20_000) {
  const before = await readTransport();
  const started = performance.now();
  const args = ['openshell', 'worker', 'run', 'proof-worker', '--target-file', input];
  const child = spawn(process.execPath, [path.join(checkout, 'dist/entry.js'), ...args], { cwd: checkout, env, stdio: ['ignore', 'pipe', 'pipe'] });
  let stdout = '', stderr = '', timedOut = false;
  child.stdout.setEncoding('utf8').on('data', value => stdout += value);
  child.stderr.setEncoding('utf8').on('data', value => stderr += value);
  const timer = setTimeout(() => { timedOut = true; child.kill('SIGKILL'); }, deadlineMs);
  const result = await new Promise((resolve, reject) => { child.once('error', reject); child.once('close', (code, signal) => resolve({ code, signal })); });
  clearTimeout(timer);
  const calls = (await readTransport()).slice(before.length);
  const cell = { label, args, ...result, timedOut, elapsedMs: Math.round(performance.now() - started), stdout, stderr, transportCalls: calls };
  receipt.calls.push(cell);
  return cell;
}
try {
  const regular = path.join(root, 'target.txt'), symlink = path.join(root, 'target-link.txt'), hardlink = path.join(root, 'target-hard.txt');
  const fifo = path.join(root, 'target.pipe'), fifoLink = path.join(root, 'target-pipe-link.txt');
  const contents = 'synthetic-single-use-target\n';
  await fs.writeFile(regular, contents, { mode: 0o600 });
  await fs.symlink(regular, symlink); await fs.link(regular, hardlink);
  execFileSync('mkfifo', [fifo]); await fs.symlink(fifo, fifoLink);
  for (const [label, input] of [['regular', regular], ['symlink', symlink], ['hardlink', hardlink]]) {
    const result = await run(label, input);
    assert.equal(result.timedOut, false); assert.equal(result.code, 1, result.stderr);
    assert.match(result.stderr, /No node was started/);
    assert.equal(result.transportCalls.length, 1, result.stderr);
    assert(result.transportCalls[0].argv.includes('attach'));
    assert(!JSON.stringify(result.transportCalls).includes('synthetic-single-use-target'));
  }
  for (const [label, input] of [['directory', workspace], ['character-device', '/dev/null'], ['fifo', fifo], ['fifo-symlink', fifoLink]]) {
    const result = await run(label, input);
    assert.equal(result.transportCalls.length, 0);
    if (expectation === 'red' && label.startsWith('fifo')) {
      assert.equal(result.timedOut, true, result.stderr); assert.equal(result.signal, 'SIGKILL');
    } else {
      assert.equal(result.timedOut, false); assert.equal(result.code, 1, result.stderr);
      assert.match(result.stderr, /regular file of at most 64 KiB/);
    }
  }
  const retry = await run('regular-retry', regular);
  assert.equal(retry.timedOut, false); assert.equal(retry.code, 1); assert.equal(retry.transportCalls.length, 1);
  assert.equal(await fs.readFile(configPath, 'utf8'), config);
  assert.equal(await fs.readFile(regular, 'utf8'), contents);
  assert((await fs.lstat(symlink)).isSymbolicLink()); assert((await fs.lstat(fifo)).isFIFO());
  receipt.readback = { configUnchanged: true, targetUnchanged: true, targetSha256: sha256(contents), linksPreserved: true, fifoPreserved: true,
    specialFileTransportCalls: 0, regularRetryReachedAttachment: true };
  receipt.status = expectation === 'red' ? 'PASS_RED' : 'PASS_GREEN';
} catch (error) { receipt.status = 'FAIL'; receipt.error = error.stack ?? String(error); process.exitCode = 1; }
await fs.writeFile(output, JSON.stringify(receipt, null, 2) + '\n');
console.log(JSON.stringify(receipt, null, 2));

