```javascript
import http from "node:http";
import { execFileSync } from "node:child_process";
import path from "node:path";
import { pathToFileURL } from "node:url";

const { VisitorPolicyClient } = await import(
  pathToFileURL(path.join(process.cwd(), "extensions/visitor-access/src/cloudflare.ts")).href
);

const config = {
  accountId: "proof-account",
  appId: "proof-app",
  apiToken: "redacted-proof-token",
  policyName: "Visitors (openclaw-managed)",
  defaultTtlDays: 14,
  maxVisitors: 50,
};
const oversizedPaddingBytes = 32 * 1024 * 1024;
let mode = "cloudflare-large";
let oversizedStats;
let oversizedClosed;

function writeJson(res, payload, status = 200) {
  res.statusCode = status;
  res.setHeader("content-type", "application/json");
  res.end(JSON.stringify(payload));
}

function writeOversizedJson(res, prefix, suffix, stats) {
  res.setHeader("content-type", "application/json");
  res.on("finish", () => {
    stats.completed = true;
  });
  oversizedClosed = new Promise((resolve) => {
    res.once("close", () => {
      stats.closed = true;
      resolve();
    });
  });
  res.write(prefix);
  stats.bytesWritten += Buffer.byteLength(prefix);
  const chunk = Buffer.alloc(1024 * 1024, 120);
  let remaining = oversizedPaddingBytes;
  const writeNext = () => {
    if (res.destroyed) {
      return;
    }
    if (remaining === 0) {
      res.end(suffix);
      return;
    }
    const next = Math.min(remaining, chunk.length);
    remaining -= next;
    stats.bytesWritten += next;
    if (!res.write(chunk.subarray(0, next))) {
      res.once("drain", writeNext);
      return;
    }
    setImmediate(writeNext);
  };
  writeNext();
}

const server = http.createServer((req, res) => {
  if (req.url !== "/cloudflare") {
    writeJson(res, { error: "not found" }, 404);
    return;
  }
  if (mode === "cloudflare-oversized") {
    oversizedStats = { bytesWritten: 0, closed: false, completed: false };
    writeOversizedJson(res, '{"success":true,"result":[],"padding":"', '"}', oversizedStats);
    return;
  }
  if (mode === "cloudflare-error") {
    writeJson(res, { success: false }, 503);
    return;
  }
  writeJson(res, {
    success: true,
    result: [],
    ...(mode === "cloudflare-large" ? { padding: "x".repeat(1024 * 1024) } : {}),
  });
});

await new Promise((resolve) => server.listen(0, "127.0.0.1", resolve));
const address = server.address();
if (!address || typeof address === "string") {
  throw new Error("missing proof server address");
}
const loopback = `http://127.0.0.1:${address.port}`;
const routeFetcher = (input, init) => fetch(`${loopback}/cloudflare`, init);
const client = () => new VisitorPolicyClient(config, routeFetcher);
const capture = async (operation) => {
  try {
    return { status: "ok", value: (await operation()) ?? null };
  } catch (error) {
    return { status: "error", message: error instanceof Error ? error.message : String(error) };
  }
};

try {
  mode = "cloudflare-large";
  const cloudflareLarge = await capture(() => client().read());
  if (cloudflareLarge.status !== "ok") {
    throw new Error(`legitimate large Cloudflare response failed: ${cloudflareLarge.message}`);
  }

  mode = "cloudflare-oversized";
  const cloudflareOversized = await capture(() => client().read());
  if (
    cloudflareOversized.status !== "error" ||
    !cloudflareOversized.message.includes("Cloudflare returned an unreadable response")
  ) {
    throw new Error("oversized Cloudflare response was not rejected by the production client");
  }
  let closeTimeout;
  await Promise.race([
    oversizedClosed,
    new Promise((resolve) => {
      closeTimeout = setTimeout(resolve, 2_000);
    }),
  ]);
  clearTimeout(closeTimeout);
  if (!oversizedStats.closed || oversizedStats.completed || oversizedStats.bytesWritten >= oversizedPaddingBytes) {
    throw new Error(
      `oversized response stream was not canceled before the full body was sent: ${JSON.stringify(oversizedStats)}`,
    );
  }

  mode = "cloudflare-error";
  const negativeControl = await capture(() => client().read());
  if (
    negativeControl.status !== "error" ||
    !negativeControl.message.includes("Cloudflare request failed (HTTP 503)")
  ) {
    throw new Error("HTTP failure control did not preserve the expected request error");
  }

  console.log(
    JSON.stringify({
      testedHead: execFileSync("git", ["rev-parse", "HEAD"], {
        cwd: process.cwd(),
        encoding: "utf8",
      }).trim(),
      productionCloudflarePolicyClient: true,
      legitimateLargeResponse: { status: cloudflareLarge.status, accepted: true },
      oversizedResponse: {
        status: cloudflareOversized.status,
        rejected: true,
        streamClosed: oversizedStats.closed,
        responseCompleted: oversizedStats.completed,
        bytesWritten: oversizedStats.bytesWritten,
        totalPaddingBytes: oversizedPaddingBytes,
      },
      negativeControl: { status: negativeControl.status, http503: true },
    }),
  );
} finally {
  server.closeAllConnections();
  await new Promise((resolve) => server.close(resolve));
}

