  console.log(`mode=${mode} CLI exit=${cli.code}`);
  // Print the unchanged CLI usage lines, rather than reconstructed snapshots.
  console.log(cli.stdout.split("\n").filter((line) => /^  (Copilot|Claude)|^\s+(5h:|Week:|Premium:|Chat:)/.test(line)).join("\n"));
  console.log("HTTP paths=" + JSON.stringify(requests));
  assert.equal(cli.code, 0, cli.stderr);
  assert(requests.includes("/copilot_internal/user"), cli.stdout + cli.stderr);
  assert(requests.includes("/api/oauth/usage"), cli.stdout + cli.stderr);
  assert(cli.stdout.includes("Claude"), cli.stdout);
  assert(cli.stdout.includes("75% left"), cli.stdout);
  const expectedCopilotLine = process.env.PROOF_EXPECT_COPILOT_LINE ?? (mode === "malformed"
    ? "Copilot: Copilot returned unreadable usage data. Try refreshing usage later."
    : "Copilot (business)");
  assert(cli.stdout.includes(expectedCopilotLine), cli.stdout);
} finally {
  server.closeAllConnections();
  await new Promise((resolve) => server.close(resolve));
  await rm(root, { recursive: true, force: true });
}
```

